window.openVersionRollback=(aid,targetVersionId)=>{const algorithm=(state.algorithms||[]).find(item=>String(item.id)===String(aid)),versions=algorithm?.versions||[],currentVersionId=String(algorithm?.current_version_id||''),current=versions.find(item=>String(item.id)===currentVersionId),target=versions.find(item=>String(item.id)===String(targetVersionId));if(!algorithm||!current||!target)return toast('版本信息已变化，请刷新算法列表后重试');if(currentVersionId===String(targetVersionId))return toast('该版本已经是当前版本');const external=String(algorithm.source_type||'').toUpperCase()==='EXTERNAL';modal('删除当前版本并回退',`<div class="version-rollback"><div class="version-rollback-algorithm"><span>算法名称</span><b>${esc(algorithm.name||algorithm.code||algorithm.id)}</b></div><div class="version-rollback-flow"><div><span>将删除</span><b>${esc(current.version_name||current.id)}</b></div><i>→</i><div><span>回到版本</span><b>${esc(target.version_name||target.id)}</b></div></div><div class="alert warn"><b>回退会删除当前版本</b><span>${external?'该算法来自新畅联，系统会先调用新畅联版本删除接口；远端删除失败时不会删除本地版本。':'删除成功后，目标历史版本自动成为当前版本。'}</span></div><div class="version-rollback-boundary">系统会先检查运行中的训练、转换和部署测试引用；存在活动引用时禁止删除。</div><div class="row end"><button class="btn soft" onclick="closeModal()">取消</button><button id="rollbackConfirmButton" class="btn danger" onclick="submitVersionRollback('${esc(aid)}','${esc(targetVersionId)}','${esc(currentVersionId)}')">确认删除并回退</button></div></div>`)};
window.submitVersionRollback=async(aid,targetVersionId,currentVersionId)=>{const button=document.getElementById('rollbackConfirmButton');if(button){button.disabled=true;button.textContent='正在删除并回退…'}const result=await safe(api(`/api/v12/projects/${pid()}/algorithms/${aid}/versions/${targetVersionId}/rollback`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({delete_current_version:true,expected_current_version_id:currentVersionId})}));if(!result){if(button){button.disabled=false;button.textContent='确认删除并回退'}return}closeModal();const runtime=window.AlgorithmListRuntime;if(!runtime?.refresh){toast('当前版本已删除，请刷新页面查看');return}await runtime.refresh({render:true});if(result.cleanup_status&&result.cleanup_status!=='cleanup_completed')toast('当前版本已删除并回退，部分物理产物清理失败，请查看操作记录');else toast('当前版本已删除，已回到目标版本')};

