  window.resumeConfirmedIterationActionCore429=async function(aid,vid){
    const a=(state.algorithms||[]).find(x=>String(x.id)===String(aid));
    const v=(a?.versions||[]).find(x=>String(x.id)===String(vid));
    const confirmed=v?.confirmed_iteration_action;
    if(!a||!v||!confirmed||confirmed.status!=='confirmed')return toast('当前版本没有已确认的迭代动作');
    const source=confirmed.source||{};
    if(String(source.algorithm_id||'')!==String(aid)||String(source.version_id||'')!==String(vid)){
      return toast('已确认动作溯源与当前版本不一致，请刷新后重试');
    }
    if(confirmed.action==='continue_training'){
      state.trainingIterationAction=confirmed;
      closeModal();
      await startAlgorithmTraining429(aid);
      setTimeout(()=>{
        const root=document.querySelector('.train429-create');
        if(root&&!root.querySelector('.iteration-action429')){
          root.insertAdjacentHTML('afterbegin',`<div class="alert ok iteration-action429"><b>已确认继续训练</b><span>基于 ${esc(v.version_name||vid)} 的持久化评测动作恢复训练草稿；只有点击“开始训练”后才会创建真实训练任务。</span></div>`);
        }
      },30);
      return;
    }
    if(confirmed.action==='supplement_data'){
      const labels=confirmed.data_draft?.weak_labels||[];
      state.iterationDataDraft=confirmed.data_draft||{};
      state.data412Labels=new Set(labels);state.data429Labels=new Set(labels);
      closeModal();setPage('数据集');
      setTimeout(()=>{
        const root=document.querySelector('.data426-shell');
        if(root&&!root.querySelector('.iteration-action429')){
          root.insertAdjacentHTML('afterbegin',`<div class="alert ok iteration-action429"><b>评测补数据草稿</b><span>来自 ${esc(v.version_name||vid)} 的已确认动作${labels.length?` · 优先标签：${labels.map(esc).join('、')}`:''}</span></div>`);
        }
      },20);
      return;
    }
    if(confirmed.action==='business_validation'){
      state.businessValidationEntry=confirmed.validation_entry||{};
      closeModal();setPage('质量中心');void window.setQualityCenterTab411?.('detect');
      setTimeout(()=>{
        const root=document.getElementById('view');
        if(root&&!root.querySelector('.iteration-action429')){
          root.insertAdjacentHTML('afterbegin',`<div class="alert ok iteration-action429"><b>已确认进入业务验证</b><span>来源版本 ${esc(v.version_name||vid)} · 继续选择真实验证/发布方式。</span></div>`);
        }
      },20);
      return;
    }
    if(confirmed.action==='manual_review'){
      const review=confirmed.review_entry||{},reasons=review.reason_codes||[],actions=review.recommended_actions||[];
      modal('人工处理记录',`<div class="report429"><section class="report429-card"><header><b>已确认人工处理</b><span>该动作来自算法版本持久化 truth</span></header><dl class="report429-dl"><dt>算法版本</dt><dd>${esc(v.version_name||vid)}</dd><dt>Decision ID</dt><dd title="${esc(source.decision_id||'')}">${esc(source.decision_id||'-')}</dd><dt>Evaluation ID</dt><dd title="${esc(source.evaluation_id||'')}">${esc(source.evaluation_id||'-')}</dd><dt>原因</dt><dd>${esc(reasons.join('、')||'-')}</dd><dt>建议</dt><dd>${esc(actions.join('、')||'-')}</dd></dl></section><div class="row end"><button class="btn" onclick="closeModal()">关闭</button></div></div>`,true);
      return;
    }
    toast('已确认动作类型不受当前页面支持');
  };

  window.confirmIterationAction429=async function(aid,vid){
    const a=(state.algorithms||[]).find(x=>String(x.id)===String(aid));
    const v=(a?.versions||[]).find(x=>String(x.id)===String(vid));
    const decision=v?.iteration_decision||{};
    const action=({needs_data:'supplement_data',continue_training:'continue_training',ready_for_business_validation:'business_validation',review_required:'manual_review'})[decision.decision];
    if(!a||!v||!action||!decision.decision_id)return toast('当前版本没有可确认的迭代动作');
    try{
      const result=await api(`/api/v12/projects/${pid()}/algorithms/${aid}/versions/${vid}/iteration-actions/confirm`,{
        method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({decision_id:decision.decision_id,action}),
      });
      v.confirmed_iteration_action=result.action||{};
      await window.resumeConfirmedIterationAction429(aid,vid);
    }catch(error){toast(error.message||error)}
  };


